CREATE TABLE backup_runtime(id INTEGER PRIMARY KEY CHECK(id=1),write_locked_until TEXT,lock_job_id TEXT);
INSERT INTO backup_runtime(id) VALUES(1);
CREATE TABLE backup_google(id INTEGER PRIMARY KEY CHECK(id=1),sealed_tokens TEXT NOT NULL,folder_id TEXT NOT NULL,connected_by TEXT NOT NULL,connected_at TEXT NOT NULL);
CREATE TABLE backup_oauth(state_hash TEXT PRIMARY KEY,staff_id TEXT NOT NULL,sealed_verifier TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE backup_jobs(id TEXT PRIMARY KEY,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('export','parts','manifest','complete','failed')),bookmark TEXT,signed_url TEXT,sql_bytes INTEGER,offset_bytes INTEGER NOT NULL DEFAULT 0,next_part INTEGER NOT NULL DEFAULT 0,counts_json TEXT NOT NULL,schema_json TEXT NOT NULL,drive_folder_id TEXT,manifest_file_id TEXT,lease_until TEXT,lease_token TEXT,attempts INTEGER NOT NULL DEFAULT 0,error_code TEXT,completed_at TEXT,alert_delivered_at TEXT);
CREATE INDEX backup_jobs_status_created ON backup_jobs(status,created_at DESC);
CREATE TABLE backup_parts(job_id TEXT NOT NULL REFERENCES backup_jobs(id),part INTEGER NOT NULL,drive_file_id TEXT NOT NULL,header_json TEXT NOT NULL,plaintext_bytes INTEGER NOT NULL,plaintext_sha256 TEXT NOT NULL,encrypted_bytes INTEGER NOT NULL,encrypted_sha256 TEXT NOT NULL,verified_at TEXT,PRIMARY KEY(job_id,part));
CREATE TRIGGER backup_guard_centers_insert BEFORE INSERT ON centers WHEN EXISTS(SELECT 1 FROM backup_runtime WHERE id=1 AND write_locked_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'backup_maintenance'); END;
CREATE TRIGGER backup_guard_centers_update BEFORE UPDATE ON centers WHEN EXISTS(SELECT 1 FROM backup_runtime WHERE id=1 AND write_locked_until>strftime('%Y-%m-%dT%H:%M:%fZ','now')) BEGIN SELECT RAISE(ABORT,'backup_maintenance'); END;
